SINA_SMART["genetics1-translation"] = {"lecture":"genetics1-translation","title":"Gene expression: translation","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"genetics1-translation:e0","text":"Codon = 3 nt; 64 codons → 20 amino acids.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e1","text":"Code: triplet, universal (not mitochondria, ciliates), degenerate, non-overlapping.","topic":"The genetic code and mRNA","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e2","text":"Mitochondria: UGA = Trp, AUA = Met.","topic":"The genetic code and mRNA","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e3","text":"Frameshift (1-2 nt indel) alters all downstream codons.","topic":"The genetic code and mRNA","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e4","text":"tRNA: cloverleaf, anticodon, CCA 3′ end; L-shape in 3D.","topic":"tRNA, synthetases, ribosomes, wobble","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e5","text":"Aminoacyl-tRNA synthetases charge tRNAs using ATP.","topic":"tRNA, synthetases, ribosomes, wobble","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e6","text":"Ribosome 80S = 40S + 60S; rRNA is the peptidyl transferase.","topic":"tRNA, synthetases, ribosomes, wobble","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e7","text":"A (aminoacyl), P (peptidyl), E (exit) sites.","topic":"tRNA, synthetases, ribosomes, wobble","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e8","text":"Wobble at the 3rd codon base explains degeneracy.","topic":"tRNA, synthetases, ribosomes, wobble","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e10","text":"Elongation: eEF1A-GTP delivers, eEF2-GTP translocates.","topic":"Initiation, elongation, termination","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e11","text":"Termination: UAA, UAG, UGA; eRF1 (GGQ) + eRF3.","topic":"Initiation, elongation, termination","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e9","text":"Initiation: eIF2-GTP + Met-tRNAi, eIF4E cap, scanning to AUG (Kozak), eIF5B joins 60S.","topic":"Initiation, elongation, termination","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-translation:e12","text":"SRP targets signal peptides to the RER.","topic":"Localisation and regulation","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1uop1p2":"a","1g01u88":"a","1x8tgmv":"a","td48bt":"a","heivzl":"a","mo9vqc":"a","1nae1mq":"a","1ytaswb":"a","1fz7sb6":"a","1k4wq1s":"a","dtdo38":"a","1ib5u72":"a","bdy5nu":"a","edlga5":"a","k51vcc":"a","15pwsk6":"a","1uxag89":"a"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"genetics1-translation:e0":{"s":0,"u":["Codon = 3 nt; 64 codons → 20 amino acids.","DNA stores information in coded form; the genetic code links codons (3 nucleotides) to amino acids: 4 bases give 64 codons for 20 amino acids .","Requirements: mRNA, ribosomes, tRNAs, amino acids, aminoacyl-tRNA synthetases, translation factors, ATP, GTP, Mg²⁺."],"dp":[]},"genetics1-translation:e1":{"s":1,"u":["Code: triplet, universal (not mitochondria, ciliates), degenerate, non-overlapping.","Properties: triplet , universal (exceptions: human mitochondria , where UGA = Trp and AUA = Met; ciliates , where UAA and UAG = Gln), degenerate (several codons per amino acid), non-overlapping , with stop codons ."],"dp":[]},"genetics1-translation:e2":{"s":1,"u":["Mitochondria: UGA = Trp, AUA = Met.","Properties: triplet , universal (exceptions: human mitochondria , where UGA = Trp and AUA = Met; ciliates , where UAA and UAG = Gln), degenerate (several codons per amino acid), non-overlapping , with stop codons ."],"dp":[]},"genetics1-translation:e3":{"s":1,"u":["Frameshift (1-2 nt indel) alters all downstream codons.","Frameshift (insertion/deletion of 1-2 nt) changes all downstream codons (e.g. cystic fibrosis, Tay-Sachs)."],"dp":[]},"genetics1-translation:e4":{"s":2,"u":["tRNA: cloverleaf, anticodon, CCA 3′ end; L-shape in 3D.","tRNA : 70-95 nt, many modified bases, ~50% paired; cloverleaf in 2D (DHU loop, anticodon loop , TΨC loop, CCA 3′ end where the amino acid attaches) and L-shape in 3D.","Aminoacyl-tRNA synthetases 'charge' tRNAs: amino acid + ATP → aminoacyl-adenylate, then transfer to the tRNA 3′ end; each enzyme is specific."],"dp":[]},"genetics1-translation:e5":{"s":2,"u":["Aminoacyl-tRNA synthetases charge tRNAs using ATP.","Aminoacyl-tRNA synthetases 'charge' tRNAs: amino acid + ATP → aminoacyl-adenylate, then transfer to the tRNA 3′ end; each enzyme is specific.","Sites: A (aminoacyl), P (peptidyl), E (exit)."],"dp":[]},"genetics1-translation:e6":{"s":2,"u":["Ribosome 80S = 40S + 60S; rRNA is the peptidyl transferase.","Ribosomes : 40S + 60S = 80S ; ~60% rRNA, 40% protein; free or on the RER; assembled in the nucleolus.","The small subunit ensures accurate decoding ; the large subunit rRNA is the peptidyl transferase (a ribozyme)."],"dp":[{"h":"Why rRNA, not protein, makes peptide bonds","t":"The peptidyl transferase centre of the large subunit is built of rRNA, with no protein close enough to catalyse the reaction. The ribosome is therefore a ribozyme, which supports the idea that RNA both stored information and catalysed reactions before proteins evolved. Source: the lecture's rRNA function slide."}]},"genetics1-translation:e7":{"s":2,"u":["A (aminoacyl), P (peptidyl), E (exit) sites.","Sites: A (aminoacyl), P (peptidyl), E (exit).","Aminoacyl-tRNA synthetases 'charge' tRNAs: amino acid + ATP → aminoacyl-adenylate, then transfer to the tRNA 3′ end; each enzyme is specific."],"dp":[]},"genetics1-translation:e8":{"s":2,"u":["Wobble at the 3rd codon base explains degeneracy.","Wobble : flexibility at the codon's 3rd base (e.g.","G-U) lets one tRNA read several codons, explaining degeneracy."],"dp":[{"h":"Why wobble saves tRNAs","t":"There are 61 sense codons, but cells need far fewer tRNAs because the third codon base pairs loosely. A tRNA with G at the matching position can read codons ending in C or U, for example. This flexibility is why many amino acids are encoded by codons differing only in the third base, and why many third-base mutations are silent. Source: the lecture's wobble hypothesis slide."}]},"genetics1-translation:e10":{"s":3,"u":["Elongation: eEF1A-GTP delivers, eEF2-GTP translocates.","Elongation : eEF1A-GTP delivers aa-tRNA to the A site (correct pairing → GTP hydrolysis, fidelity checkpoint); peptidyl transferase moves the chain onto the A-site tRNA; eEF2-GTP translocates one codon (A→P, P→E) via hybrid states.","Initiation : eIF1, 1A, 3, 5 bind 40S; eIF2-GTP brings the initiator Met-tRNAi into the P site → 43S . eIF4E binds the cap; eIF4G scaffolds; eIF4A/B helicase unwinds the 5′ UTR; eIF4G-eIF3 recruit the 43S → 48S , which scans 5′→3′ to the first AUG in a Kozak context; eIF2 hydrolyses GTP and leaves; eIF5B-GTP joins the 60S → 80S ."],"dp":[]},"genetics1-translation:e11":{"s":3,"u":["Termination: UAA, UAG, UGA; eRF1 (GGQ) + eRF3.","Termination : stop codons UAA, UAG, UGA recognised by eRF1 ; eRF3-GTP escorts it; eRF1's GGQ motif releases the peptide; Rli1 helps recycle subunits."],"dp":[]},"genetics1-translation:e9":{"s":3,"u":["Initiation: eIF2-GTP + Met-tRNAi, eIF4E cap, scanning to AUG (Kozak), eIF5B joins 60S.","Initiation : eIF1, 1A, 3, 5 bind 40S; eIF2-GTP brings the initiator Met-tRNAi into the P site → 43S . eIF4E binds the cap; eIF4G scaffolds; eIF4A/B helicase unwinds the 5′ UTR; eIF4G-eIF3 recruit the 43S → 48S , which scans 5′→3′ to the first AUG in a Kozak context; eIF2 hydrolyses GTP and leaves; eIF5B-GTP joins the 60S → 80S ."],"dp":[]},"genetics1-translation:e12":{"s":4,"u":["SRP targets signal peptides to the RER.","ER-bound ribosomes make secreted and membrane proteins: a signal peptide is recognised by the signal recognition particle (SRP) , which guides the ribosome to the RER for co-translational translocation."],"dp":[]}},"meta":{"1uop1p2":{"a":"recall","vg":"genetics1-translation:e0/recall/1"},"1g01u88":{"a":"recall","vg":"genetics1-translation:e0/recall/1"},"1x8tgmv":{"a":"recall","vg":"genetics1-translation:e2/recall/1"},"td48bt":{"a":"relationship","vg":"genetics1-translation:e3/relationship/1"},"heivzl":{"a":"recall","vg":"genetics1-translation:e4/recall/1"},"mo9vqc":{"a":"recall","vg":"genetics1-translation:e5/recall/1"},"1nae1mq":{"a":"recall","vg":"genetics1-translation:e6/recall/1"},"1ytaswb":{"a":"recall","vg":"genetics1-translation:e6/recall/2"},"1fz7sb6":{"a":"recall","vg":"genetics1-translation:e7/recall/1"},"1k4wq1s":{"a":"recall","vg":"genetics1-translation:e8/recall/1"},"dtdo38":{"a":"recall","vg":"genetics1-translation:e9/recall/1"},"1ib5u72":{"a":"recall","vg":"genetics1-translation:e9/recall/2"},"bdy5nu":{"a":"recall","vg":"genetics1-translation:e9/recall/3"},"edlga5":{"a":"recall","vg":"genetics1-translation:e10/recall/1"},"k51vcc":{"a":"recall","vg":"genetics1-translation:e11/recall/1"},"15pwsk6":{"a":"recall","vg":"genetics1-translation:e11/recall/2"},"1uxag89":{"a":"recall","vg":"genetics1-translation:e12/recall/1"}},"explRev":"2b43c191ae91"};
